//! C: i3-config-wizard/main.c (1040 lines) — Program to convert configs using
//! keycodes to configs using keysyms.
//!
//! The wizard has three separable pieces:
//!
//! * the config generator (finish()), which reads SYSCONFDIR/i3/config.keycodes
//!   and rewrites every "bindcode" line into a "bindsym" line. The output is
//!   byte-exact with C: the C template strings are taken over verbatim.
//! * the binding parser (rewrite_binding()/next_state()), which drives the
//!   config parser's token tables (GENERATED_config_tokens.h in C, generated by
//!   i3-spec from the same parser-specs/config.spec here) and turns the
//!   keycode/modifier tokens into a keysym name via the keymap.
//! * the UI (welcome/generate steps, key and button handling), which is drawn
//!   through the WizardRenderer seam so tests can record the calls and compare
//!   them 1:1 with C.
//!
//! The keymap lookups are behind the Keymap trait: the real implementation uses
//! x11rb's xkb extension plus the core keyboard mapping (libxkbcommon is not
//! used), the tests use a fixed keymap.

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]

use std::io::Write;

use i3_spec::config_parser::{config_tokens, ConfigState, ConfigToken};
use i3_spec::parser_util::{
    parser_clear_stack, parser_get_string, parser_push_long, parser_push_string, Stack,
};
use libi3::draw_util::color_t;
use libi3::string::{i3string_from_utf8, i3String};

