/// C: main.c:711-712 XK_Return / XK_KP_Enter
const XK_Return: u32 = 0xff0d;
const XK_KP_Enter: u32 = 0xff8d;
/// C: X11/keysymdef.h XK_Up / XK_Down
const XK_Up: u32 = 0xff52;
const XK_Down: u32 = 0xff54;
/// C: X11/keysymdef.h XK_Escape
const XK_Escape: u32 = 0xff1b;
/// C: xcb/xproto.h XCB_MOD_MASK_LOCK
const XCB_MOD_MASK_LOCK: u16 = 1 << 1;
/// C: x11rb / xcb NONE
const XCB_NONE: u8 = 0;

/// C: main.c:235 static bool keysym_used_on_other_key(KeySym sym,
/// xcb_keycode_t except_keycode) — the keymap half of it.
pub trait Keymap {
    /// C: xcb_get_setup(conn)->min_keycode
    fn min_keycode(&self) -> u8;
    /// C: xcb_get_setup(conn)->max_keycode
    fn max_keycode(&self) -> u8;
    /// C: xkb_keymap_key_get_syms_by_level(xkb_keymap, keycode, 0, level, &syms)
    ///
    /// Returns the symbols (C returns a pointer and a count; level 0 is group
    /// 0/level 0). An empty vector is the C "num == 0" case.
    fn key_get_syms_by_level(&mut self, keycode: u8, level: i32) -> Vec<u32>;
    /// C: xkb_keysym_get_name(syms[0], str, sizeof(str)) — None is the C -1.
    fn keysym_get_name(&mut self, sym: u32) -> Option<String>;
    /// C: xcb_key_symbols_get_keysym(keysyms, keycode, level)
    fn key_symbols_get_keysym(&mut self, keycode: u8, level: i32) -> u32;
    /// C: xcb_key_press_lookup_keysym(symbols, event, col) — the event is
    /// reduced to its keycode and the (state filtered) column.
    fn key_press_lookup_keysym(&mut self, keycode: u8, col: i32) -> u32;
}

/// C: main.c:235-252 keysym_used_on_other_key()
///
/// Returns true if sym is bound to any key except for except_keycode on the
/// first four layers (normal, shift, mode_switch, mode_switch + shift).
pub fn keysym_used_on_other_key(keymap: &mut dyn Keymap, sym: u32, except_keycode: u8) -> bool {
    let min_keycode = keymap.min_keycode();
    let max_keycode = keymap.max_keycode();

    // C: for (i = min_keycode; i && i <= max_keycode; i++)
    let mut i = min_keycode;
    while i != 0 && i <= max_keycode {
        if i != except_keycode {
            for level in 0..4 {
                if keymap.key_symbols_get_keysym(i, level) != sym {
                    continue;
                }
                return true;
            }
        }
        i = i.wrapping_add(1);
    }
    false
}

/// C: libc strncasecmp(3) — the literal token comparison of rewrite_binding().
fn strncasecmp(a: &[u8], b: &[u8], n: usize) -> i32 {
    for i in 0..n {
        let ca = a.get(i).copied().unwrap_or(0).to_ascii_lowercase();
        let cb = b.get(i).copied().unwrap_or(0).to_ascii_lowercase();
        if ca != cb {
            return ca as i32 - cb as i32;
        }
        if ca == 0 {
            return 0;
        }
    }
    0
}

/// C: libc atoi(3)
pub fn atoi(s: &str) -> i64 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] == b' ' || (0x09..=0x0d).contains(&bytes[i])) {
        i += 1;
    }
    let mut sign = 1i64;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        i += 1;
    }
    sign * value
}

/// C: main.c:126 static cmdp_state state; statelist/statelist_idx; the stack.
///
/// C keeps these as file statics; the port owns them in a struct so that the
/// binding parser is re-entrant (the same reason the config parser keeps them
/// in its context).
pub struct binding_parser {
    /// C: static cmdp_state state
    pub state: ConfigState,
    /// C: static cmdp_state statelist[10] = {INITIAL}; int statelist_idx = 1
    pub statelist: [ConfigState; 10],
    /// C: static int statelist_idx = 1
    pub statelist_idx: usize,
    /// C: static struct stack_entry stack[10]
    pub stack: Stack,
}

impl Default for binding_parser {
    fn default() -> Self {
        binding_parser {
            state: ConfigState::INITIAL,
            statelist: [ConfigState::INITIAL; 10],
            statelist_idx: 1,
            stack: Stack::default(),
        }
    }
}

impl binding_parser {
    /// C: main.c:254 static char *next_state(const cmdp_token *token)
    fn next_state(&mut self, token: &ConfigToken, keymap: &mut dyn Keymap) -> Option<String> {
        let _next_state = token.next_state;

        if token.next_state == ConfigState::__CALL {
            return Some(self.binding_from_tokens(keymap));
        }

        self.state = _next_state;

        /* C: See if we are jumping back to a state in which we were in
         * previously (statelist contains INITIAL) and just move statelist_idx
         * accordingly. */
        for i in 0..self.statelist_idx {
            if self.statelist[i] as i32 != _next_state as i32 {
                continue;
            }
            self.statelist_idx = i + 1;
            return None;
        }

        /* C: Otherwise, the state is new and we add it to the list.
         * (C writes statelist[statelist_idx] without a bounds check; the port
         * keeps the index inside the array instead of corrupting memory.) */
        if self.statelist_idx < self.statelist.len() {
            self.statelist[self.statelist_idx] = _next_state;
            self.statelist_idx += 1;
        }
        None
    }

    /// C: main.c:257-311 — the __CALL branch of next_state(): build the
    /// "bindsym ..." line from the collected tokens.
    fn binding_from_tokens(&mut self, keymap: &mut dyn Keymap) -> String {
        let modifiers = parser_get_string(&self.stack, "modifiers").map(|s| s.to_string());
        let key = parser_get_string(&self.stack, "key").unwrap_or("").to_string();
        let keycode = atoi(&key);
        let mut level = 0i32;
        if let Some(modifiers) = &modifiers {
            if modifiers.contains("Shift") {
                /* C: When shift is included, we really need to use the
                 * second-level symbol (upper-case). */
                level = 1;

                /* C: Try to use the keysym on the first level (lower-case). In
                 * case this doesn't make it ambiguous, we'll stick with the
                 * keysym of the first level. */
                let syms = keymap.key_get_syms_by_level(keycode as u8, 0);
                if syms.is_empty() {
                    libi3::errx(
                        1,
                        &format!(
                            "xkb_keymap_key_get_syms_by_level returned no symbols for keycode {}",
                            keycode
                        ),
                    );
                }
                if !keysym_used_on_other_key(keymap, syms[0], keycode as u8) {
                    level = 0;
                }
            }
        }

        let syms = keymap.key_get_syms_by_level(keycode as u8, level);
        if syms.is_empty() {
            libi3::errx(
                1,
                &format!(
                    "xkb_keymap_key_get_syms_by_level returned no symbols for keycode {}",
                    keycode
                ),
            );
        }
        if syms.len() > 1 {
            // C: printf("... returned %d symbolsinstead of 1, using only the first one.\n", ...)
            println!(
                "xkb_keymap_key_get_syms_by_level (keycode = {}) returned {} symbolsinstead of 1, using only the first one.",
                keycode,
                syms.len()
            );
        }

        let name = match keymap.keysym_get_name(syms[0]) {
            Some(name) => name,
            None => libi3::errx(1, &format!("xkb_keysym_get_name({}) failed", syms[0])),
        };

        let release = parser_get_string(&self.stack, "release").map(|s| s.to_string());
        let modrep = match &modifiers {
            Some(m) => m.replace(',', "+"),
            None => String::new(),
        };
        let command = parser_get_string(&self.stack, "command")
            .unwrap_or("")
            .to_string();
        let res = format!(
            "bindsym {}{}{} {}{}\n",
            if modifiers.is_none() { "" } else { &modrep },
            if modifiers.is_none() { "" } else { "+" },
            name,
            release.unwrap_or_default(),
            command
        );
        parser_clear_stack(&mut self.stack);
        res
    }

    /// C: main.c:330 static char *rewrite_binding(const char *input)
    pub fn rewrite_binding(&mut self, input: &str, keymap: &mut dyn Keymap) -> Option<String> {
        self.state = ConfigState::INITIAL;
        self.statelist_idx = 1;

        let bytes = input.as_bytes();
        let len = bytes.len();
        let mut walk = 0usize;

        /* C: The "<=" operator is intentional: We also handle the terminating
         * 0-byte explicitly by looking for an 'end' token. */
        loop {
            if walk > len {
                break;
            }
            /* C: Skip whitespace before every token, newlines are relevant
             * since they separate configuration directives. */
            while walk < len && (bytes[walk] == b' ' || bytes[walk] == b'\t') {
                walk += 1;
            }

            let tokens = config_tokens(self.state);
            let mut consumed = false;

            for token in tokens {
                /* A literal. */
                if token.name.as_bytes().first() == Some(&b'\'') {
                    let literal = &token.name.as_bytes()[1..];
                    if strncasecmp(&bytes[walk.min(len)..], literal, literal.len()) == 0 {
                        if let Some(identifier) = token.identifier {
                            parser_push_string(&mut self.stack, identifier, &token.name[1..]);
                        }
                        walk += literal.len();
                        if let Some(result) = self.next_state(token, keymap) {
                            return Some(result);
                        }
                        consumed = true;
                        break;
                    }
                    continue;
                }

                if token.name == "number" {
                    /* C: Handle numbers. We only accept decimal numbers for
                     * now. */
                    match strtol(&bytes[walk.min(len)..]) {
                        Some((num, used)) => {
                            if let Some(identifier) = token.identifier {
                                parser_push_long(&mut self.stack, identifier, num);
                            }
                            /* C: Set walk to the first non-number character */
                            walk += used;
                            if let Some(result) = self.next_state(token, keymap) {
                                return Some(result);
                            }
                            consumed = true;
                            break;
                        }
                        None => continue,
                    }
                }

                if token.name == "string" || token.name == "word" {
                    let mut beginning = walk;
                    let mut w = walk;
                    /* C: Handle quoted strings (or words). */
                    if bytes.get(w).copied().unwrap_or(0) == b'"' {
                        beginning += 1;
                        w += 1;
                        while byte_at(bytes, w) != 0
                            && (byte_at(bytes, w) != b'"' || byte_at(bytes, w - 1) == b'\\')
                        {
                            w += 1;
                        }
                    } else if token.name.as_bytes()[0] == b's' {
                        while byte_at(bytes, w) != 0
                            && byte_at(bytes, w) != b'\r'
                            && byte_at(bytes, w) != b'\n'
                        {
                            w += 1;
                        }
                    } else {
                        /* C: For a word, the delimiters are white space (' ' or
                         * '\t'), closing square bracket (]), comma (,) and
                         * semicolon (;). */
                        while byte_at(bytes, w) != b' '
                            && byte_at(bytes, w) != b'\t'
                            && byte_at(bytes, w) != b']'
                            && byte_at(bytes, w) != b','
                            && byte_at(bytes, w) != b';'
                            && byte_at(bytes, w) != b'\r'
                            && byte_at(bytes, w) != b'\n'
                            && byte_at(bytes, w) != 0
                        {
                            w += 1;
                        }
                    }
                    if w != beginning {
                        /* C: We copy manually to handle escaping of
                         * characters (only \" is unescaped). */
                        let mut out: Vec<u8> = Vec::with_capacity(w - beginning);
                        let mut inpos = beginning;
                        while inpos < w {
                            if bytes[inpos] == b'\\'
                                && bytes.get(inpos + 1).copied().unwrap_or(0) == b'"'
                            {
                                inpos += 1;
                            }
                            out.push(bytes[inpos]);
                            inpos += 1;
                        }
                        let str_value = String::from_utf8_lossy(&out).into_owned();
                        if let Some(identifier) = token.identifier {
                            parser_push_string(&mut self.stack, identifier, &str_value);
                        }
                        /* C: If we are at the end of a quoted string, skip the
                         * ending double quote. */
                        if byte_at(bytes, w) == b'"' {
                            w += 1;
                        }
                        walk = w;
                        if let Some(result) = self.next_state(token, keymap) {
                            return Some(result);
                        }
                        consumed = true;
                        break;
                    }
                    /* C: falls through to the "end" check below */
                }

                if token.name == "end" {
                    let b = byte_at(bytes, walk);
                    if b == 0 || b == b'\n' || b == b'\r' {
                        if let Some(result) = self.next_state(token, keymap) {
                            return Some(result);
                        }
                        /* C: To make sure we start with an appropriate matching
                         * data structure for commands which do *not* specify
                         * any criteria, we re-initialize the criteria system
                         * after every command. */
                        walk += 1;
                        consumed = true;
                        break;
                    }
                }
            }

            if !consumed {
                /* No token matched the input: the C loop would spin forever
                 * here, the port gives up instead. */
                return None;
            }
        }

        None
    }
}

/// Byte at an index, or the NUL terminator like C string indexing with a
/// properly terminated buffer.
fn byte_at(bytes: &[u8], index: usize) -> u8 {
    bytes.get(index).copied().unwrap_or(0)
}

/// C: libc strtol(3) base 10 — returns the value and the number of bytes
/// consumed, or None when no digits were found (C: end == walk) or the value
/// overflows (C: errno == ERANGE).
pub fn strtol(bytes: &[u8]) -> Option<(i64, usize)> {
    let mut i = 0;
    while i < bytes.len() && (bytes[i] == b' ' || (0x09..=0x0d).contains(&bytes[i])) {
        i += 1;
    }
    let start_digits = {
        let mut j = i;
        if j < bytes.len() && (bytes[j] == b'+' || bytes[j] == b'-') {
            j += 1;
        }
        j
    };
    let mut value: i64 = 0;
    let mut j = start_digits;
    let negative = i < bytes.len() && bytes[i] == b'-';
    let mut overflow = false;
    while j < bytes.len() && bytes[j].is_ascii_digit() {
        match value
            .checked_mul(10)
            .and_then(|v| v.checked_add((bytes[j] - b'0') as i64))
        {
            Some(v) => value = v,
            None => {
                overflow = true;
                break;
            }
        }
        j += 1;
    }
    if j == start_digits {
        return None;
    }
    if overflow {
        return None;
    }
    Some((if negative { -value } else { value }, j))
}

/* ---------------------------------------------------------------------------
 * C: main.c:674 static void finish(void) — the config file generation. The
 * output is byte-identical to C: the header lines and the "set \(mod" line are
 * the C template strings, every other line is copied verbatim, and "bindcode"
 * lines go through rewrite_binding().
 * ------------------------------------------------------------------------- */

/// C: main.c:707-712 — the header written to the generated config.
pub const GENERATED_HEADER: &str = "# This file has been auto-generated by i3-config-wizard(1).\n\
# It will not be overwritten, so edit it as you like.\n\
#\n\
# Should you change your keyboard layout some time, delete\n\
# this file and re-run i3-config-wizard(1).\n\
#\n";

/// C: main.c:722-760 — the getline() loop of finish() over the template.
///
/// The C code reads SYSCONFDIR/i3/config.keycodes and writes config_path; the
/// port reads the template as a string and writes to any writer, so the file
/// handling stays in the binary and the transform is testable.
pub fn finish(
    keymap: &mut dyn Keymap,
    template: &str,
    out: &mut dyn Write,
    modifier: Modifier,
) -> std::io::Result<()> {
    let mut parser = binding_parser::default();

    /* C: write a header about auto-generation to the output file */
    out.write_all(GENERATED_HEADER.as_bytes())?;

    let mut head_of_file = true;

    for line in template.split_inclusive('\n') {
        let len = line.len();
        let bytes = line.as_bytes();

        /* C: skip the warning block at the beginning of the input file */
        if head_of_file && line.starts_with("# WARNING") {
            continue;
        }

        head_of_file = false;

        /* C: Skip leading whitespace */
        let mut i = 0usize;
        while i < len && isspace(bytes[i]) {
            /* C: Pre-output the skipped whitespaces to keep proper indentation */
            out.write_all(&bytes[i..i + 1])?;
            i += 1;
        }

        let walk = &line[i..];

        /* C: Set the modifier the user chose */
        if walk.starts_with("set $mod ") {
            if modifier == Modifier::MOD_Mod1 {
                out.write_all(b"set $mod Mod1\n")?;
            } else {
                out.write_all(b"set $mod Mod4\n")?;
            }
            continue;
        }

        /* C: Check for 'bindcode'. If it's not a bindcode line, we just copy it
         * to the output file. */
        if !walk.starts_with("bindcode") {
            out.write_all(walk.as_bytes())?;
            continue;
        }
        match parser.rewrite_binding(walk, keymap) {
            Some(result) => out.write_all(result.as_bytes())?,
            // C: fputs(NULL) would crash; a binding that cannot be parsed is
            // dropped instead.
            None => {}
        }
    }

    /* C: sync to do our best in order to have the file really stored on disk —
     * the caller flushes/fsyncs its file. */
    out.flush()?;
    Ok(())
}

/// C: ctype.h isspace()
pub fn isspace(byte: u8) -> bool {
    byte == b' ' || (0x09..=0x0d).contains(&byte)
}

/// The drawing surface of the wizard (C: surface_t surface plus the fonts).
pub trait WizardRenderer {
    /// C: libi3/dpi.c:85 logical_px()
    fn logical_px(&mut self, logical: i32) -> i32;
    /// C: libi3/draw_util.c:163 draw_util_hex_to_color()
    fn hex_to_color(&mut self, color: &str) -> color_t;
    /// C: libi3/draw_util.c:283 draw_util_clear_surface()
    fn clear_surface(&mut self, color: color_t);
    /// C: libi3/draw_util.c:209 draw_util_text()
    fn text(
        &mut self,
        text: &mut i3String,
        fg_color: color_t,
        bg_color: color_t,
        x: i32,
        y: i32,
        max_width: i32,
    );
    /// C: libi3/font.c:256 set_font(&font) / set_font(&bold_font)
    fn set_font_bold(&mut self, bold: bool);
    /// C: font.height
    fn font_height(&self) -> i32;
    /// C: char_width (predict_text_width(i3string_from_utf8("a")))
    fn char_width(&self) -> i32;
    /// C: xcb_flush(conn)
    fn flush(&mut self);
    /// C: main.c:586-593 / :964-971 — xcb_change_property(win, A__NET_WM_NAME,
    /// A_UTF8_STRING, 8, strlen(title), title)
    fn set_window_title(&mut self, title: &str);
}

/// C: main.c:87-103 — the file statics of the wizard (everything that is not
/// needed by the pure logic).
pub struct Wizard {
    /// C: static char *config_path
    pub config_path: String,
    /// C: enum { STEP_WELCOME, STEP_GENERATE } current_step
    pub current_step: Step,
    /// C: enum { MOD_Mod1, MOD_Mod4 } modifier
    pub modifier: Modifier,
    /// C: uint32_t xcb_numlock_mask
    pub xcb_numlock_mask: u32,
}

impl Default for Wizard {
    fn default() -> Self {
        Wizard {
            config_path: String::new(),
            current_step: Step::STEP_WELCOME,
            modifier: Modifier::MOD_Mod4,
            xcb_numlock_mask: 0,
        }
    }
}

impl Wizard {
    /// C: main.c:495-501 static void txt(int col, int row, char *text,
    /// color_t fg, color_t bg)
    fn txt(
        &mut self,
        col: i32,
        row: i32,
        text: &str,
        fg: color_t,
        bg: color_t,
        renderer: &mut dyn WizardRenderer,
    ) {
        let text_padding = renderer.logical_px(TEXT_PADDING_LOGICAL);
        let win_width = renderer.logical_px(WIN_WIDTH_LOGICAL);
        let char_width = renderer.char_width();
        let font_height = renderer.font_height();

        let x = col_x(col, char_width, text_padding);
        let y = row_y(row, font_height, text_padding);
        let mut string = i3string_from_utf8(text);
        renderer.text(
            &mut string,
            fg,
            bg,
            x,
            y,
            win_width - x - text_padding,
        );
        libi3::string::i3string_free(Some(string));
    }
}

/// C: main.c:77-78 #define col_x(col) (((col) - 1) * char_width + TEXT_PADDING)
pub fn col_x(col: i32, char_width: i32, text_padding: i32) -> i32 {
    (col - 1) * char_width + text_padding
}

/// C: main.c:79-80 #define row_y(row) (((row) - 1) * font.height + TEXT_PADDING)
pub fn row_y(row: i32, font_height: i32, text_padding: i32) -> i32 {
    (row - 1) * font_height + text_padding
}

/// C: main.c:507 static int handle_expose(void)
///
/// Handles expose events, that is, draws the window contents.
pub fn handle_expose(wizard: &mut Wizard, renderer: &mut dyn WizardRenderer) -> i32 {
    let black = renderer.hex_to_color("#000000");
    let white = renderer.hex_to_color("#FFFFFF");
    let green = renderer.hex_to_color("#00FF00");
    let red = renderer.hex_to_color("#FF0000");

    /* draw background */
    renderer.clear_surface(black);

    renderer.set_font_bold(false);

    if wizard.current_step == Step::STEP_WELCOME {
        wizard.txt(2, 2, "You have not configured i3 yet.", white, black, renderer);
        wizard.txt(2, 3, "Do you want me to generate a config at", white, black, renderer);

        let msg = format!("{}?", wizard.config_path);
        wizard.txt(2, 4, &msg, white, black, renderer);

        wizard.txt(13, 6, "Yes, generate the config", white, black, renderer);
        wizard.txt(13, 8, "No, I will use the defaults", white, black, renderer);

        wizard.txt(4, 6, "<Enter>", green, black, renderer);

        wizard.txt(5, 8, "<ESC>", red, black, renderer);
    }

    if wizard.current_step == Step::STEP_GENERATE {
        wizard.txt(2, 2, "Please choose either:", white, black, renderer);
        wizard.txt(13, 4, "Win as default modifier", white, black, renderer);
        wizard.txt(13, 5, "Alt as default modifier", white, black, renderer);
        wizard.txt(2, 7, "Afterwards, press", white, black, renderer);
        wizard.txt(13, 9, "to write the config", white, black, renderer);
        wizard.txt(13, 10, "to abort", white, black, renderer);

        /* the not-selected modifier */
        if wizard.modifier == Modifier::MOD_Mod4 {
            wizard.txt(5, 5, "<Alt>", white, black, renderer);
        } else {
            wizard.txt(5, 4, "<Win>", white, black, renderer);
        }

        /* the selected modifier */
        renderer.set_font_bold(true);
        if wizard.modifier == Modifier::MOD_Mod4 {
            wizard.txt(2, 4, "-> <Win>", white, black, renderer);
        } else {
            wizard.txt(2, 5, "-> <Alt>", white, black, renderer);
        }

        renderer.set_font_bold(false);
        wizard.txt(4, 9, "<Enter>", green, black, renderer);

        wizard.txt(5, 10, "<ESC>", red, black, renderer);
    }

    renderer.flush();

    1
}

/// What a key press does (C: the key press handler calls finish()/exit()).
#[derive(Debug, PartialEq, Eq)]
pub enum KeyOutcome {
    Continue,
    /// C: finish() — write the config and tell i3 to reload.
    Finish,
    /// C: exit(0)
    Exit,
}

/// C: main.c:569 static int handle_key_press(void *ignored,
/// xcb_connection_t *conn, xcb_key_press_event_t *event)
pub fn handle_key_press(
    wizard: &mut Wizard,
    keycode: u8,
    state: u16,
    keysyms: &mut dyn Keymap,
    modmap: &[u8],
    keycodes_per_modifier: usize,
    renderer: &mut dyn WizardRenderer,
) -> KeyOutcome {
    println!("Keypress {}, state raw = {}", keycode, state);

    /* C: Remove the numlock bit, all other bits are modifiers we can bind to.
     * Only use the lower 8 bits of the state (modifier masks) so that mouse
     * button masks are filtered out. */
    let mut state_filtered = state & !(wizard.xcb_numlock_mask as u16 | XCB_MOD_MASK_LOCK);
    state_filtered &= 0xFF;

    // C: xcb_key_press_lookup_keysym(symbols, event, state_filtered) — the C
    // code passes the modifier mask as the column, kept 1:1.
    let sym = keysyms.key_press_lookup_keysym(keycode, state_filtered as i32);

    println!("sym = {} ({})", (sym & 0xff) as u8 as char, sym);

    if sym == XK_Return || sym == XK_KP_Enter {
        if wizard.current_step == Step::STEP_WELCOME {
            wizard.current_step = Step::STEP_GENERATE;
            /* C: Set window title */
            renderer.set_window_title("i3: generate config");
        } else {
            return KeyOutcome::Finish;
        }
    }

    /* C: Swap between modifiers when up or down is pressed. */
    if sym == XK_Up || sym == XK_Down {
        wizard.modifier = if wizard.modifier == Modifier::MOD_Mod1 {
            Modifier::MOD_Mod4
        } else {
            Modifier::MOD_Mod1
        };
        handle_expose(wizard, renderer);
    }

    /* C: cancel any time */
    if sym == XK_Escape {
        return KeyOutcome::Exit;
    }

    /* C: Check if this is Mod1 or Mod4. The modmap contains Shift, Lock,
     * Control, Mod1, Mod2, Mod3, Mod4, Mod5 (in that order). */
    /* Mod1? */
    let mask = 3usize;
    for i in 0..keycodes_per_modifier {
        let code = modmap
            .get(mask * keycodes_per_modifier + i)
            .copied()
            .unwrap_or(XCB_NONE);
        if code == XCB_NONE {
            continue;
        }
        println!("Modifier keycode for Mod1: 0x{:02x}", code);
        if code == keycode {
            wizard.modifier = Modifier::MOD_Mod1;
            println!("This is Mod1!");
        }
    }

    /* Mod4? */
    let mask = 6usize;
    for i in 0..keycodes_per_modifier {
        let code = modmap
            .get(mask * keycodes_per_modifier + i)
            .copied()
            .unwrap_or(XCB_NONE);
        if code == XCB_NONE {
            continue;
        }
        println!("Modifier keycode for Mod4: 0x{:02x}", code);
        if code == keycode {
            wizard.modifier = Modifier::MOD_Mod4;
            println!("This is Mod4!");
        }
    }

    handle_expose(wizard, renderer);
    KeyOutcome::Continue
}

/// C: main.c:650 static void handle_button_press(xcb_button_press_event_t *event)
///
/// Handle button presses to make clicking on "<win>" and "<alt>" work.
pub fn handle_button_press(
    wizard: &mut Wizard,
    event_x: i16,
    event_y: i16,
    renderer: &mut dyn WizardRenderer,
) {
    if wizard.current_step != Step::STEP_GENERATE {
        return;
    }

    let text_padding = renderer.logical_px(TEXT_PADDING_LOGICAL);
    let char_width = renderer.char_width();
    let font_height = renderer.font_height();

    if event_x < col_x(5, char_width, text_padding) as i16
        || event_x > col_x(10, char_width, text_padding) as i16
    {
        return;
    }

    let row4 = row_y(4, font_height, text_padding) as i16;
    let row5 = row_y(5, font_height, text_padding) as i16;

    if event_y >= row4 && event_y <= row4 + font_height as i16 {
        wizard.modifier = Modifier::MOD_Mod4;
        handle_expose(wizard, renderer);
    }

    if event_y >= row5 && event_y <= row5 + font_height as i16 {
        wizard.modifier = Modifier::MOD_Mod1;
        handle_expose(wizard, renderer);
    }
}

/* ---------------------------------------------------------------------------
 * The keymap implementations.
 * ------------------------------------------------------------------------- */

pub fn keysym_name(sym: u32) -> Option<String> {
    let name = match sym {
        0x20..=0x7e => {
            if (sym as u8).is_ascii_alphanumeric() {
                ((sym as u8) as char).to_string()
            } else {
                let punct = match sym as u8 {
                    b' ' => "space",
                    b'!' => "exclam",
                    b'"' => "quotedbl",
                    b'#' => "numbersign",
                    b'$' => "dollar",
                    b'%' => "percent",
                    b'&' => "ampersand",
                    b'\'' => "apostrophe",
                    b'(' => "parenleft",
                    b')' => "parenright",
                    b'*' => "asterisk",
                    b'+' => "plus",
                    b',' => "comma",
                    b'-' => "minus",
                    b'.' => "period",
                    b'/' => "slash",
                    b':' => "colon",
                    b';' => "semicolon",
                    b'<' => "less",
                    b'=' => "equal",
                    b'>' => "greater",
                    b'?' => "question",
                    b'@' => "at",
                    b'[' => "bracketleft",
                    b'\\' => "backslash",
                    b']' => "bracketright",
                    b'^' => "asciicircum",
                    b'_' => "underscore",
                    0x60 => "grave",
                    b'{' => "braceleft",
                    b'|' => "bar",
                    b'}' => "braceright",
                    b'~' => "asciitilde",
                    _ => return None,
                };
                punct.to_string()
            }
        }
        0xff08 => "BackSpace".to_string(),
        0xff09 => "Tab".to_string(),
        0xff0d => "Return".to_string(),
        0xff1b => "Escape".to_string(),
        0xff50 => "Home".to_string(),
        0xff51 => "Left".to_string(),
        0xff52 => "Up".to_string(),
        0xff53 => "Right".to_string(),
        0xff54 => "Down".to_string(),
        0xff55 => "Prior".to_string(),
        0xff56 => "Next".to_string(),
        0xff57 => "End".to_string(),
        0xff63 => "Insert".to_string(),
        0xffff => "Delete".to_string(),
        0xff7e => "Mode_switch".to_string(),
        0xffbe..=0xffc9 => format!("F{}", sym - 0xffbe + 1),
        0xffe1 => "Shift_L".to_string(),
        0xffe3 => "Control_L".to_string(),
        0xffe9 => "Alt_L".to_string(),
        0xffeb => "Super_L".to_string(),
        _ => return None,
    };
    Some(name)
}

pub struct XkbKeymap {
    pub min_keycode: u8,
    pub max_keycode: u8,
    pub syms_per_code: usize,
    pub syms: Vec<u32>,
}

/// C: xcb/xcb_keysyms.h XCB_NUM_LOCK — the keysym the wizard asks
/// get_mod_mask_for() about (xkbcommon spells it XKB_KEY_Num_Lock).
pub const XCB_NUM_LOCK: u32 = 0xff7f;

impl XkbKeymap {
    pub fn new(conn: &x11rb::rust_connection::RustConnection) -> XkbKeymap {
        use x11rb::connection::Connection;
        use x11rb::protocol::xproto::ConnectionExt;

        let min_keycode = conn.setup().min_keycode;
        let max_keycode = conn.setup().max_keycode;
        let count = (max_keycode - min_keycode + 1) as u8;
        let reply = conn
            .get_keyboard_mapping(min_keycode, count)
            .ok()
            .and_then(|cookie| cookie.reply().ok());
        match reply {
            Some(reply) => XkbKeymap {
                min_keycode,
                max_keycode,
                syms_per_code: reply.keysyms.len() / (count.max(1)) as usize,
                syms: reply.keysyms.iter().map(|k| *k as u32).collect(),
            },
            None => XkbKeymap {
                min_keycode,
                max_keycode,
                syms_per_code: 0,
                syms: Vec::new(),
            },
        }
    }

    fn symbol(&self, keycode: u8, level: i32) -> u32 {
        if keycode < self.min_keycode || keycode > self.max_keycode {
            return 0;
        }
        let mut level = level as usize;
        if level >= self.syms_per_code {
            level = 0;
        }
        let idx = (keycode - self.min_keycode) as usize * self.syms_per_code + level;
        *self.syms.get(idx).unwrap_or(&0)
    }
}

impl Keymap for XkbKeymap {
    fn min_keycode(&self) -> u8 {
        self.min_keycode
    }
    fn max_keycode(&self) -> u8 {
        self.max_keycode
    }
    fn key_get_syms_by_level(&mut self, keycode: u8, level: i32) -> Vec<u32> {
        let sym = self.symbol(keycode, level);
        if sym == 0 {
            return Vec::new();
        }
        vec![sym]
    }
    fn keysym_get_name(&mut self, sym: u32) -> Option<String> {
        keysym_name(sym)
    }
    fn key_symbols_get_keysym(&mut self, keycode: u8, level: i32) -> u32 {
        self.symbol(keycode, level)
    }
    fn key_press_lookup_keysym(&mut self, keycode: u8, col: i32) -> u32 {
        self.symbol(keycode, col)
    }
}

pub struct Libi3Renderer<'a> {
    pub conn: &'a x11rb::rust_connection::RustConnection,
    pub win: u32,
    pub font: libi3::font::i3Font,
    pub bold_font: libi3::font::i3Font,
    pub bold: bool,
    pub char_width: i32,
    /// C: the surface_t the drawing calls write to (surface_t::none() means
    /// "not initialized yet", which the draw_util_* functions skip).
    pub surface: libi3::draw_util::surface_t,
}

impl<'a> WizardRenderer for Libi3Renderer<'a> {
    fn logical_px(&mut self, logical: i32) -> i32 {
        libi3::dpi::logical_px(logical)
    }
    fn hex_to_color(&mut self, color: &str) -> color_t {
        libi3::draw_util::draw_util_hex_to_color(color)
    }
    fn clear_surface(&mut self, color: color_t) {
        libi3::draw_util::draw_util_clear_surface(self.conn, &mut self.surface, color);
    }
    fn text(
        &mut self,
        text: &mut i3String,
        fg_color: color_t,
        bg_color: color_t,
        x: i32,
        y: i32,
        max_width: i32,
    ) {
        libi3::draw_util::draw_util_text(
            self.conn,
            text,
            &mut self.surface,
            fg_color,
            bg_color,
            x,
            y,
            max_width,
        );
    }
    fn set_font_bold(&mut self, bold: bool) {
        self.bold = bold;
        if bold {
            libi3::font::set_font(&self.bold_font);
        } else {
            libi3::font::set_font(&self.font);
        }
    }
    fn font_height(&self) -> i32 {
        self.font.height
    }
    fn char_width(&self) -> i32 {
        self.char_width
    }
    fn flush(&mut self) {
        use x11rb::connection::Connection;
        let _ = self.conn.flush();
    }
    fn set_window_title(&mut self, title: &str) {
        use x11rb::protocol::xproto::{ConnectionExt, PropMode};
        use x11rb::wrapper::ConnectionExt as WrapperExt;
        let name_atom = self
            .conn
            .intern_atom(false, b"_NET_WM_NAME")
            .ok()
            .and_then(|c| c.reply().ok())
            .map(|r| r.atom);
        let utf8_atom = self
            .conn
            .intern_atom(false, b"UTF8_STRING")
            .ok()
            .and_then(|c| c.reply().ok())
            .map(|r| r.atom);
        if let (Some(name_atom), Some(utf8_atom)) = (name_atom, utf8_atom) {
            let _ = self.conn.change_property8(
                PropMode::REPLACE,
                self.win,
                name_atom,
                utf8_atom,
                title.as_bytes(),
            );
        }
    }
}

pub struct Options {
    pub socket_path: Option<String>,
    pub modifier: Modifier,
    pub headless_run: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            socket_path: None,
            modifier: Modifier::MOD_Mod4,
            headless_run: false,
        }
    }
}

pub enum ParseOutcome {
    Version,
    Help,
    Run(Options),
}

fn long_options() -> Vec<libi3::getopt::option> {
    use libi3::getopt::{no_argument, required_argument, option};
    vec![
        option { name: "socket", has_arg: required_argument, val: b's' },
        option { name: "version", has_arg: no_argument, val: b'v' },
        option { name: "modifier", has_arg: required_argument, val: b'm' },
        option { name: "limit", has_arg: required_argument, val: b'l' },
        option { name: "prompt", has_arg: required_argument, val: b'P' },
        option { name: "prefix", has_arg: required_argument, val: b'p' },
        option { name: "font", has_arg: required_argument, val: b'f' },
        option { name: "help", has_arg: no_argument, val: b'h' },
    ]
}

pub fn parse_args(argv: Vec<std::ffi::OsString>) -> ParseOutcome {
    use libi3::getopt::{getopt_long, Getopt};

    let mut go = Getopt::new(argv);
    let opts = long_options();
    let options_string = "sm:vh";

    let mut parsed = Options::default();

    loop {
        let o = getopt_long(&mut go, options_string, &opts);
        if o == -1 {
            break;
        }
        let optarg = || go.optarg.as_ref().map(|a| a.to_string_lossy().into_owned());
        if o == b's' as i32 {
            parsed.socket_path = optarg();
        } else if o == b'v' as i32 {
            return ParseOutcome::Version;
        } else if o == b'm' as i32 {
            parsed.headless_run = true;
            let value = optarg().unwrap_or_default();
            if value == "alt" {
                parsed.modifier = Modifier::MOD_Mod1;
            } else if value == "win" {
                parsed.modifier = Modifier::MOD_Mod4;
            } else {
                libi3::err(1, &format!("Invalid modifier key {}", value));
            }
        } else if o == b'h' as i32 {
            return ParseOutcome::Help;
        }
    }

    ParseOutcome::Run(parsed)
}

pub fn print_version() {
    print!("i3-config-wizard {}\n", libi3::i3_version());
}

pub fn print_help() {
    print_version();
    print!("i3-config-wizard [-s <socket>] [-m win|alt] [-v] [-h]\n");
}

fn finish_file(
    conn: &x11rb::rust_connection::RustConnection,
    config_path: &str,
    modifier: Modifier,
    socket_path: Option<&str>,
) -> ! {
    println!("creating \"{}\"...", config_path);

    let mut keymap = XkbKeymap::new(conn);

    let keycodes_path = format!("{}/i3/config.keycodes", libi3::SYSCONFDIR);
    let template = match std::fs::read_to_string(&keycodes_path) {
        Ok(t) => t,
        Err(_) => libi3::err(
            1,
            &format!("Could not open input file \"{}\"", keycodes_path),
        ),
    };

    let mut file = match std::fs::File::create(config_path) {
        Ok(f) => f,
        Err(_) => libi3::err(
            1,
            &format!("Could not open output config file \"{}\"", config_path),
        ),
    };

    if finish(&mut keymap, &template, &mut file, modifier).is_err() {
        libi3::err(1, &format!("Could not write \"{}\"", config_path));
    }

    let _ = file.sync_all();
    drop(file);

    let sockfd = libi3::ipc_connect(socket_path);
    libi3::ipc_send_message(sockfd, 6, 0, b"reload");
    unsafe {
        libc::close(sockfd);
    }

    std::process::exit(0)
}

fn run_wizard(
    conn: x11rb::rust_connection::RustConnection,
    screen: usize,
    opts: &Options,
    config_path: &str,
) -> i32 {
    use x11rb::connection::Connection;
    use x11rb::protocol::xproto::{
        ConnectionExt, CreateWindowAux, EventMask, PropMode, WindowClass,
    };
    use x11rb::wrapper::ConnectionExt as WrapperExt;

    let root_screen = match conn.setup().roots.get(screen) {
        Some(s) => s,
        None => libi3::errx(1, "Cannot open display"),
    };
    let root = root_screen.root;

    use x11rb::protocol::xkb::ConnectionExt as XkbExt;
    if conn.xkb_use_extension(1, 0).is_err() {
        libi3::errx(1, "Could not setup XKB extension.");
    }

    let modmap_cookie = conn.get_modifier_mapping();
    let mut keysyms = XkbKeymap::new(&conn);

    if opts.headless_run {
        finish_file(&conn, config_path, opts.modifier, opts.socket_path.as_deref());
    }

    let modmap_reply = match modmap_cookie.ok().and_then(|c| c.reply().ok()) {
        Some(r) => r,
        None => libi3::errx(1, "Could not get modifier mapping"),
    };

    // C: i3-config-wizard/main.c:907 xcb_numlock_mask = get_mod_mask_for(
    //     XCB_NUM_LOCK, symbols, modmap_reply). xcb_key_symbols_alloc() is
    //     libi3's X11KeySymbols (one GetKeyboardMapping round trip).
    let numlock_mask = match libi3::get_mod_mask::X11KeySymbols::new(&conn) {
        Some(symbols) => {
            libi3::get_mod_mask::get_mod_mask_for(&symbols, XCB_NUM_LOCK, &modmap_reply.keycodes)
        }
        // C: xcb_key_symbols_get_keycode() returning NULL answers 0.
        None => 0,
    };

    let mut wizard = Wizard {
        config_path: config_path.to_string(),
        current_step: Step::STEP_WELCOME,
        modifier: opts.modifier,
        xcb_numlock_mask: numlock_mask,
    };

    libi3::dpi::init_dpi(Some(&conn));
    let font = libi3::font::load_font(Some(&conn), "pango:monospace 8", true);
    let bold_font = libi3::font::load_font(Some(&conn), "pango:monospace bold 8", true);
    libi3::font::set_font(&font);
    let mut char_width_string = i3string_from_utf8("a");
    let char_width = libi3::font::predict_text_width(Some(&conn), &mut char_width_string);
    libi3::string::i3string_free(Some(char_width_string));

    let text_padding = libi3::dpi::logical_px(TEXT_PADDING_LOGICAL);
    let win_pos_x = libi3::dpi::logical_px(WIN_POS_X_LOGICAL);
    let win_pos_y = libi3::dpi::logical_px(WIN_POS_Y_LOGICAL);
    let win_width = libi3::dpi::logical_px(WIN_WIDTH_LOGICAL);
    let win_height = WIN_HEIGHT_ROWS * font.height + text_padding;

    let win = match conn.generate_id() {
        Ok(w) => w,
        Err(_) => libi3::errx(1, "Cannot generate window id"),
    };

    let _ = conn.create_window(
        x11rb::COPY_FROM_PARENT as u8,
        win,
        root,
        win_pos_x as i16,
        win_pos_y as i16,
        win_width as u16,
        win_height as u16,
        0,
        WindowClass::INPUT_OUTPUT,
        x11rb::COPY_FROM_PARENT,
        &CreateWindowAux::new()
            .background_pixel(0)
            .event_mask(EventMask::EXPOSURE | EventMask::BUTTON_PRESS),
    );
    let _ = conn.map_window(win);

    let atom_names = [
        "_NET_WM_NAME",
        "_NET_WM_WINDOW_TYPE",
        "_NET_WM_WINDOW_TYPE_DIALOG",
        "ATOM",
        "CARDINAL",
        "UTF8_STRING",
    ];
    let mut atoms: Vec<u32> = Vec::new();
    for name in atom_names {
        match conn.intern_atom(false, name.as_bytes()) {
            Ok(cookie) => match cookie.reply() {
                Ok(reply) => atoms.push(reply.atom),
                Err(_) => libi3::errx(1, &format!("Could not get atom {}", name)),
            },
            Err(_) => libi3::errx(1, &format!("Could not get atom {}", name)),
        }
    }

    let _ = conn.change_property32(PropMode::REPLACE, win, atoms[1], atoms[3], &[atoms[2]]);

    let title = "i3: first configuration";
    let _ = conn.change_property8(PropMode::REPLACE, win, atoms[0], atoms[5], title.as_bytes());

    let _ = conn.flush();

    use x11rb::protocol::xproto::{GrabMode, GrabStatus};
    let mut status = GrabStatus::ALREADY_GRABBED;
    let mut count_retries = 0;
    loop {
        let reply = conn
            .grab_keyboard(
                false,
                win,
                x11rb::CURRENT_TIME,
                GrabMode::ASYNC,
                GrabMode::ASYNC,
            )
            .ok()
            .and_then(|cookie| cookie.reply().ok());
        match reply {
            Some(reply) => {
                status = reply.status;
                if status == GrabStatus::SUCCESS || count_retries >= 500 {
                    break;
                }
            }
            None => {
                if count_retries >= 500 {
                    break;
                }
            }
        }
        count_retries += 1;
        std::thread::sleep(std::time::Duration::from_micros(1000));
    }

    if status != GrabStatus::SUCCESS {
        eprintln!("Could not grab keyboard, status = {}", u8::from(status));
        return -1;
    }

    let _ = conn.flush();

    let mut renderer = Libi3Renderer {
        conn: &conn,
        win,
        font,
        bold_font,
        bold: false,
        char_width,
        // C: draw_util_surface_init() for the wizard window.
        surface: libi3::draw_util::surface_t::none(),
    };

    let keycodes_per_modifier = modmap_reply.keycodes_per_modifier() as usize;
    let modmap_keycodes = modmap_reply.keycodes;

    loop {
        use x11rb::protocol::Event;
        let event = match conn.wait_for_event() {
            Ok(e) => e,
            Err(_) => break,
        };
        match event {
            Event::Error(e) => {
                eprintln!("X11 Error received! sequence {:x}", e.sequence);
            }
            Event::KeyPress(e) => {
                match handle_key_press(
                    &mut wizard,
                    e.detail,
                    u16::from(e.state),
                    &mut keysyms,
                    &modmap_keycodes,
                    keycodes_per_modifier,
                    &mut renderer,
                ) {
                    KeyOutcome::Continue => {}
                    KeyOutcome::Finish => {
                        finish_file(
                            &conn,
                            &wizard.config_path,
                            wizard.modifier,
                            opts.socket_path.as_deref(),
                        );
                    }
                    KeyOutcome::Exit => return 0,
                }
            }
            Event::ButtonPress(e) => {
                handle_button_press(&mut wizard, e.event_x, e.event_y, &mut renderer);
            }
            Event::Expose(e) => {
                if e.count == 0 {
                    handle_expose(&mut wizard, &mut renderer);
                }
            }
            _ => {}
        }
    }

    let _ = conn.flush();
    0
}

pub fn run_with_args(argv: Vec<std::ffi::OsString>) -> i32 {
    let opts = match parse_args(argv) {
        ParseOutcome::Version => {
            print_version();
            return 0;
        }
        ParseOutcome::Help => {
            print_help();
            return 0;
        }
        ParseOutcome::Run(o) => o,
    };

    if let Some(path) = libi3::get_config_path(None, false) {
        println!("The config file \"{}\" already exists. Exiting.", path);
        return 0;
    }

    let xdg_config_home =
        std::env::var("XDG_CONFIG_HOME").unwrap_or_else(|_| "~/.config".to_string());
    let xdg_config_home = libi3::resolve_tilde(&xdg_config_home);
    let config_path = format!("{}/i3/config", xdg_config_home);

    let config_dir = format!("{}/i3", xdg_config_home);
    let mut statbuf: libc::stat = unsafe { std::mem::zeroed() };
    let c_dir = std::ffi::CString::new(config_dir.clone()).unwrap_or_default();
    if unsafe { libc::stat(c_dir.as_ptr(), &mut statbuf) } != 0 {
        if libi3::mkdirp(&config_dir, libi3::DEFAULT_DIR_MODE) != 0 {
            libi3::err(1, &format!("mkdirp({}) failed", config_dir));
        }
    }

    let c_path = std::ffi::CString::new(config_path.clone()).unwrap_or_default();
    let fd = unsafe { libc::open(c_path.as_ptr(), libc::O_CREAT | libc::O_RDWR, 0o644) };
    if fd == -1 {
        println!(
            "Cannot open file \"{}\" for writing: {}. Exiting.",
            config_path,
            libi3::err::strerror(std::io::Error::last_os_error().raw_os_error().unwrap_or(0))
        );
        return 0;
    }
    unsafe {
        libc::close(fd);
        libc::unlink(c_path.as_ptr());
    }

    let (conn, screen) = match x11rb::rust_connection::RustConnection::connect(None) {
        Ok(c) => c,
        Err(_) => libi3::errx(1, "Cannot open display"),
    };

    run_wizard(conn, screen, &opts, &config_path)
}

pub fn run() -> i32 {
    run_with_args(std::env::args_os().collect())
}
